[package]
name = "api"
version = "0.1.0"
edition = "2021"

[features]
default = []
server = ["dioxus-fullstack/server"]

[dependencies]
dioxus = { workspace = true, features = ["fullstack"] }
dioxus-fullstack = "*"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
chrono = { version = "0.4", features = ["serde"] }
uuid = { version = "1.0", features = ["v4", "serde", "js"] }
once_cell = "1.19"
thiserror = "1.0"
validator = { version = "0.18", features = ["derive"] }
anyhow = "1.0"

# Phase 6: Internationalization
fluent = "0.16"
fluent-bundle = "0.15"
unic-langid = "0.9"

# Phase 7: Encryption & Sync
rand = "0.8"
getrandom = { workspace = true, features = ["js"] }

# Server-only dependencies (only available on non-WASM targets)
[target.'cfg(not(target_arch = "wasm32"))'.dependencies]
dioxus-server = "*"
tokio = { version = "1.0", features = ["sync", "macros", "rt-multi-thread", "fs", "io-util"] }
tokio-util = { version = "0.7", features = ["rt"] }
sqlx = { version = "0.7", features = ["runtime-tokio-rustls", "sqlite", "chrono", "uuid"] }
aes-gcm = { version = "0.10" }
argon2 = { version = "0.5" }
bcrypt = { version = "0.15" }
statrs = { version = "0.17" }
ndarray = { version = "0.15" }
